/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 1: CSS RESET & NORMALIZATION
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  font-family: 'Inter', 'Montserrat', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: linear-gradient(135deg, #0a1128 0%, #050814 50%, #000000 100%);
  color: #c0c0c0;
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 2: CSS CUSTOM PROPERTIES (DARK THEME)
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

:root {
  /* ── Background Colors ── */
  --bg0: #0a1128;
  --bg1: #0f172a;
  --bg2: #111827;
  --bg3: #1a2333;
  --bg4: #1e2a3a;
  --bg5: #243545;
  --bg6: #2a4055;
  --bg7: #304b65;
  --bg-glass: rgba(15, 23, 42, 0.75);
  --bg-card: rgba(26, 35, 51, 0.85);
  --bg-hover: rgba(212, 175, 55, 0.08);
  
  /* ── Accent Colors (Neon Glow) ── */
  --blue: #00d4ff;
  --blue-glow: 0, 212, 255;
  --purple: #bf00ff;
  --purple-glow: 191, 0, 255;
  --green: #00ff88;
  --green-glow: 0, 255, 136;
  --yellow: #ffae00;
  --yellow-glow: 255, 174, 0;
  --gold: #d4af37;
  --gold-glow: 212, 175, 55;
  --red: #ff4444;
  --red-glow: 255, 68, 68;
  
  /* ── Alpha Variants ── */
  --blue-10: rgba(0, 212, 255, 0.1);
  --blue-20: rgba(0, 212, 255, 0.2);
  --blue-30: rgba(0, 212, 255, 0.3);
  --purple-10: rgba(191, 0, 255, 0.1);
  --purple-20: rgba(191, 0, 255, 0.2);
  --green-10: rgba(0, 255, 136, 0.1);
  --green-20: rgba(0, 255, 136, 0.2);
  --gold-10: rgba(212, 175, 55, 0.1);
  --gold-20: rgba(212, 175, 55, 0.2);
  --gold-30: rgba(212, 175, 55, 0.3);
  
  /* ── Text Colors ── */
  --text-primary: #ffffff;
  --text-secondary: #c0c0c0;
  --text-tertiary: #8a8a8a;
  --text-muted: #6b6b6b;
  --text-gold: #d4af37;
  --text-blue: #00d4ff;
  --text-green: #00ff88;
  --text-purple: #bf00ff;
  --text-yellow: #ffae00;
  
  /* ── Border Colors ── */
  --border-light: rgba(255, 255, 255, 0.05);
  --border-medium: rgba(255, 255, 255, 0.1);
  --border-strong: rgba(255, 255, 255, 0.15);
  --border-gold: rgba(212, 175, 55, 0.3);
  --border-blue: rgba(0, 212, 255, 0.3);
  --border-purple: rgba(191, 0, 255, 0.3);
  --border-green: rgba(0, 255, 136, 0.3);
  
  /* ── Typography ── */
  --font-heading: 'Playfair Display', 'Inter', 'Poppins', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', 'Montserrat', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
  --font-brand: 'Orbitron', 'Inter', system-ui, -apple-system, sans-serif; /* matches NAME.png logo */
  
  /* ── Font Sizes ── */
  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  
  /* ── Spacing ── */
  --spacing-0: 0;
  --spacing-1: 0.25rem;
  --spacing-2: 0.5rem;
  --spacing-3: 0.75rem;
  --spacing-4: 1rem;
  --spacing-5: 1.25rem;
  --spacing-6: 1.5rem;
  --spacing-8: 2rem;
  --spacing-10: 2.5rem;
  --spacing-12: 3rem;
  --spacing-16: 4rem;
  --spacing-20: 5rem;
  --spacing-24: 6rem;
  
  /* ── Border Radii ── */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-3xl: 2rem;
  --radius-full: 9999px;
  
  /* ── Shadows ── */
  --shadow-xs: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
  --shadow-2xl: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
  --shadow-glow: 0 0 20px rgba(212, 175, 55, 0.3);
  --shadow-glow-blue: 0 0 20px rgba(0, 212, 255, 0.3);
  --shadow-glow-purple: 0 0 20px rgba(191, 0, 255, 0.3);
  --shadow-glow-green: 0 0 20px rgba(0, 255, 136, 0.3);
  
  /* ── Transitions ── */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 300ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-spring: 400ms cubic-bezier(0.34, 1.56, 0.64, 1);
  
  /* ── Z-Index ── */
  --z-negative: -1;
  --z-0: 0;
  --z-10: 10;
  --z-20: 20;
  --z-30: 30;
  --z-40: 40;
  --z-50: 50;
  --z-auto: auto;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 3: LIGHT THEME OVERRIDES
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

[data-theme="light"] {
  --bg0: #f8fafc;
  --bg1: #f1f5f9;
  --bg2: #e2e8f0;
  --bg3: #cbd5e1;
  --bg4: #94a3b8;
  --bg5: #64748b;
  --bg6: #475569;
  --bg7: #334155;
  --bg-glass: rgba(248, 250, 252, 0.75);
  --bg-card: rgba(226, 232, 240, 0.85);
  
  --text-primary: #0f172a;
  --text-secondary: #334155;
  --text-tertiary: #64748b;
  --text-muted: #94a3b8;
  
  --border-light: rgba(0, 0, 0, 0.05);
  --border-medium: rgba(0, 0, 0, 0.1);
  --border-strong: rgba(0, 0, 0, 0.15);
  
  --gold: #c9a96e;
  --gold-glow: 201, 169, 110;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 4: FONT SIZE VARIANTS
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

[data-font="small"] {
  font-size: 14px;
}

[data-font="medium"] {
  font-size: 16px;
}

[data-font="large"] {
  font-size: 18px;
}

[data-font="xlarge"] {
  font-size: 20px;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 5: CUSTOM SCROLLBAR
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: rgba(15, 23, 42, 0.5);
  border-radius: 10px;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(135deg, #00d4ff, #bf00ff);
  border-radius: 10px;
  transition: all 0.3s ease;
}

::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(135deg, #d4af37, #ffae00);
}

* {
  scrollbar-width: thin;
  scrollbar-color: #00d4ff rgba(15, 23, 42, 0.5);
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 6: TYPOGRAPHY
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  background: linear-gradient(135deg, #ffffff, #d4af37);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  letter-spacing: -0.02em;
}

h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
}

h2 {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  margin-bottom: 1rem;
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
}

h4 {
  font-size: clamp(1rem, 2.5vw, 1.25rem);
}

p {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--text-secondary);
  margin-bottom: 1rem;
}

a {
  color: #00d4ff;
  text-decoration: none;
  transition: all 0.3s ease;
  position: relative;
}

a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 1px;
  background: linear-gradient(90deg, #00d4ff, #d4af37);
  transition: width 0.3s ease;
}

a:hover::after {
  width: 100%;
}

a:hover {
  color: #d4af37;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 7: SELECTION & FOCUS
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

::selection {
  background: rgba(0, 212, 255, 0.3);
  color: #ffffff;
}

::-moz-selection {
  background: rgba(0, 212, 255, 0.3);
  color: #ffffff;
}

:focus {
  outline: none;
}

:focus-visible {
  outline: 2px solid #00d4ff;
  outline-offset: 2px;
  border-radius: 4px;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 8: BACKGROUND PARTICLES & EFFECTS
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

body::before {
  content: '';
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: 
    radial-gradient(circle at 20% 30%, rgba(0, 212, 255, 0.08) 0%, transparent 50%),
    radial-gradient(circle at 80% 70%, rgba(191, 0, 255, 0.08) 0%, transparent 50%),
    radial-gradient(circle at 40% 80%, rgba(0, 255, 136, 0.05) 0%, transparent 50%),
    radial-gradient(circle at 90% 20%, rgba(212, 175, 55, 0.08) 0%, transparent 50%);
  pointer-events: none;
  z-index: 0;
  animation: gradientFlow 20s ease infinite;
}

body::after {
  content: '';
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(255, 255, 255, 0.02) 2px,
    rgba(255, 255, 255, 0.02) 4px
  );
  pointer-events: none;
  z-index: 0;
}

@keyframes gradientFlow {
  0%, 100% { opacity: 0.5; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.05); }
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 9: ANIMATIONS LIBRARY (50+ ANIMATIONS)
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

/* Fade Animations */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes fadeOut {
  from { opacity: 1; }
  to { opacity: 0; }
}

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeDown {
  from {
    opacity: 0;
    transform: translateY(-30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeLeft {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes fadeRight {
  from {
    opacity: 0;
    transform: translateX(-30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* Scale Animations */
@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.9);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes scaleOut {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.9);
  }
}

@keyframes scalePulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.05); }
}

/* Slide Animations */
@keyframes slideInLeft {
  from {
    opacity: 0;
    transform: translateX(-100%);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(100%);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slideInUp {
  from {
    opacity: 0;
    transform: translateY(100%);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideInDown {
  from {
    opacity: 0;
    transform: translateY(-100%);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Rotate Animations */
@keyframes rotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes spinSlow {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes spinReverse {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(-360deg); }
}

/* Pulse Animations */
@keyframes pulse {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.5;
    transform: scale(0.98);
  }
}

@keyframes pulseGlow {
  0%, 100% {
    box-shadow: 0 0 5px rgba(0, 212, 255, 0.5), 0 0 10px rgba(0, 212, 255, 0.3);
  }
  50% {
    box-shadow: 0 0 20px rgba(0, 212, 255, 0.8), 0 0 30px rgba(0, 212, 255, 0.5);
  }
}

@keyframes pulseSoft {
  0%, 100% { opacity: 0.6; }
  50% { opacity: 1; }
}

@keyframes pulseStrong {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.1); opacity: 0.8; }
}

/* Neon Pulse Animations */
@keyframes firePulse {
  0%, 100% {
    text-shadow: 0 0 5px #ffae00, 0 0 10px #ffae00;
  }
  50% {
    text-shadow: 0 0 20px #ffae00, 0 0 30px #ffae00, 0 0 40px #ffae00;
  }
}

@keyframes icePulse {
  0%, 100% {
    text-shadow: 0 0 5px #00d4ff, 0 0 10px #00d4ff;
  }
  50% {
    text-shadow: 0 0 20px #00d4ff, 0 0 30px #00d4ff;
  }
}

@keyframes neonPulse {
  0%, 100% {
    box-shadow: 0 0 5px #bf00ff, 0 0 10px #bf00ff, inset 0 0 5px #bf00ff;
  }
  50% {
    box-shadow: 0 0 20px #bf00ff, 0 0 30px #bf00ff, inset 0 0 10px #bf00ff;
  }
}

/* Float Animations */
@keyframes float {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

@keyframes floatSlow {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-15px);
  }
}

@keyframes floatFast {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-5px);
  }
}

/* Shine & Shimmer Animations */
@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

@keyframes shine {
  0% {
    left: -100%;
  }
  100% {
    left: 100%;
  }
}

@keyframes glowPulse {
  0%, 100% {
    filter: drop-shadow(0 0 5px rgba(212, 175, 55, 0.5));
  }
  50% {
    filter: drop-shadow(0 0 20px rgba(212, 175, 55, 0.8));
  }
}

/* Typewriter Animations */
@keyframes blinkCursor {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

@keyframes wave {
  0%, 100% { transform: rotate(0deg); }
  25% { transform: rotate(15deg); }
  75% { transform: rotate(-15deg); }
}

/* Bounce & Shake Animations */
@keyframes bounce {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-15px);
  }
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  75% { transform: translateX(5px); }
}

@keyframes wobble {
  0%, 100% { transform: translateX(0); }
  15% { transform: translateX(-8px); }
  30% { transform: translateX(6px); }
  45% { transform: translateX(-4px); }
  60% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes jello {
  0%, 100% { transform: scale3d(1, 1, 1); }
  30% { transform: scale3d(1.25, 0.75, 1); }
  40% { transform: scale3d(0.75, 1.25, 1); }
  50% { transform: scale3d(1.15, 0.85, 1); }
  65% { transform: scale3d(0.95, 1.05, 1); }
  75% { transform: scale3d(1.05, 0.95, 1); }
}

/* Gradient Animations */
@keyframes gradientShift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Particle Animations */
@keyframes particleFloat {
  0% {
    transform: translateY(0) translateX(0);
    opacity: 1;
  }
  100% {
    transform: translateY(-100px) translateX(20px);
    opacity: 0;
  }
}

@keyframes particleDrift {
  0% {
    transform: translateY(0) translateX(0);
    opacity: 0.5;
  }
  50% {
    opacity: 1;
  }
  100% {
    transform: translateY(-50px) translateX(-20px);
    opacity: 0;
  }
}

/* Utility Animation Classes */
.fade-in { animation: fadeIn 0.5s ease forwards; }
.fade-up { animation: fadeUp 0.6s ease forwards; }
.fade-down { animation: fadeDown 0.6s ease forwards; }
.scale-in { animation: scaleIn 0.4s ease forwards; }
.slide-right { animation: slideInRight 0.5s ease forwards; }
.slide-left { animation: slideInLeft 0.5s ease forwards; }
.pulse-animation { animation: pulse 2s ease infinite; }
.pulse-glow { animation: pulseGlow 2s ease infinite; }
.float-animation { animation: float 3s ease infinite; }
.spin-slow { animation: spinSlow 8s linear infinite; }
.spin-reverse { animation: spinReverse 10s linear infinite; }
.shimmer { background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent); background-size: 200% 100%; animation: shimmer 2s infinite; }

