/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 11: BUTTONS & INTERACTIVE ELEMENTS
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 28px;
  border: none;
  border-radius: 50px;
  font-family: 'Inter', sans-serif;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  overflow: hidden;
}

.btn::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
  transform: translate(-50%, -50%);
  transition: width 0.6s, height 0.6s;
}

.btn:hover::before {
  width: 300px;
  height: 300px;
}

.btn-primary {
  background: linear-gradient(135deg, #00d4ff, #0099cc);
  color: #ffffff;
  box-shadow: 0 4px 15px rgba(0, 212, 255, 0.3);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(0, 212, 255, 0.4);
}

.btn-primary:active {
  transform: translateY(1px);
}

.btn-gold {
  background: linear-gradient(135deg, #d4af37, #b8941f);
  color: #0a1128;
  font-weight: 700;
  box-shadow: 0 4px 15px rgba(212, 175, 55, 0.3);
}

.btn-gold:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(212, 175, 55, 0.4);
}

.btn-purple {
  background: linear-gradient(135deg, #bf00ff, #8a00cc);
  color: #ffffff;
  box-shadow: 0 4px 15px rgba(191, 0, 255, 0.3);
}

.btn-green {
  background: linear-gradient(135deg, #00ff88, #00cc66);
  color: #0a1128;
  box-shadow: 0 4px 15px rgba(0, 255, 136, 0.3);
}

.btn-outline {
  background: transparent;
  border: 2px solid rgba(0, 212, 255, 0.5);
  color: #00d4ff;
}

.btn-outline:hover {
  border-color: #00d4ff;
  background: rgba(0, 212, 255, 0.1);
  transform: translateY(-2px);
}

.btn-glass {
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #ffffff;
}

.btn-glass:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(212, 175, 55, 0.3);
  transform: translateY(-2px);
}

.btn-icon {
  width: 42px;
  height: 42px;
  padding: 0;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 12: INPUT FIELDS & FORMS
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

input, textarea, select {
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  padding: 14px 18px;
  font-family: 'Inter', sans-serif;
  font-size: 0.95rem;
  color: #ffffff;
  transition: all 0.3s ease;
}

input:focus, textarea:focus, select:focus {
  border-color: #00d4ff;
  box-shadow: 0 0 0 3px rgba(0, 212, 255, 0.2);
  outline: none;
}

input:hover, textarea:hover, select:hover {
  border-color: rgba(0, 212, 255, 0.5);
}

input::placeholder, textarea::placeholder {
  color: rgba(255, 255, 255, 0.3);
}

.input-group {
  position: relative;
  margin-bottom: 20px;
}

.input-label {
  display: block;
  margin-bottom: 8px;
  font-size: 0.85rem;
  font-weight: 500;
  color: #00d4ff;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.input-icon {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(255, 255, 255, 0.4);
  pointer-events: none;
}

.input-icon + input {
  padding-left: 48px;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 13: LAYOUT & GRID SYSTEMS
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

.container {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 24px;
}

.grid {
  display: grid;
  gap: 24px;
}

.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-5 { grid-template-columns: repeat(5, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

.flex {
  display: flex;
}

.flex-col {
  flex-direction: column;
}

.items-center {
  align-items: center;
}

.justify-center {
  justify-content: center;
}

.justify-between {
  justify-content: space-between;
}

.gap-1 { gap: 4px; }
.gap-2 { gap: 8px; }
.gap-3 { gap: 12px; }
.gap-4 { gap: 16px; }
.gap-5 { gap: 20px; }
.gap-6 { gap: 24px; }
.gap-8 { gap: 32px; }
.gap-10 { gap: 40px; }

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 14: DASHBOARD LAYOUT (LEFT PANEL & RIGHT PANEL)
   ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════ */

.dash-root {
  display: flex;
  flex-direction: column;
  height: 100vh;
  overflow: hidden;
}

.dash-body {
  flex: 1;
  display: flex;
  overflow: hidden;
  position: relative;
}

/* Left Panel (Sidebar) */
.left-panel {
  width: 320px;
  background: rgba(5, 8, 20, 0.98);
  backdrop-filter: blur(24px);
  border-right: 1px solid rgba(255, 255, 255, 0.05);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 100;
}

.left-panel.collapsed {
  transform: translateX(-320px);
}

/* Right Panel (Main Content) */
.right-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  position: relative;
}

