  .wizard-tool-badge { font-size: .58rem; }

  /* Wizard buttons smaller */
  .wizard-btn { padding: 8px 14px; font-size: .78rem; }

  /* Depth/Style grid — 2 cols */
  .wizard-depth-grid, .wizard-style-grid { grid-template-columns: 1fr 1fr; }
  .wizard-depth-card, .wizard-style-card { padding: 10px; }
  .wizard-depth-card i, .wizard-style-card i { font-size: .95rem; }
  .wizard-depth-name, .wizard-style-name { font-size: .78rem; }

  /* Mega modal options */
  .mega-options { grid-template-columns: 1fr; }

  /* Flashcard height on mobile */
  .fc-face { padding: 18px; }
  .fc-content { font-size: .85rem; max-height: 140px; }

  /* Empty state */
  .es-cta-row { flex-direction: column; align-items: center; }
  .empty-mega-btn { font-size: .85rem; padding: 12px 22px; }

  /* Demo dots */
  .demo-dot { width: 24px; height: 24px; font-size: .62rem; }
}

@media (max-width: 480px) {
  /* Stats grid — 4 col on mobile */
  .stats-grid-sidebar { grid-template-columns: repeat(4,1fr); }
  .stat-value-sidebar { font-size: .85rem; }

  /* Wizard tool grid — 1 col on tiny screens */
  .wizard-tool-grid { grid-template-columns: 1fr; }

  /* Demo footer stack */
  .demo-footer { flex-direction: column; gap: 10px; }
  .demo-nav-btn { width: 100%; justify-content: center; }

  /* Wizard steps scroll */
  .wizard-steps {
    overflow-x: auto;
    flex-wrap: nowrap;
    padding-bottom: 6px;
    scrollbar-width: none;
    -ms-overflow-style: none;
  }
  .wizard-steps::-webkit-scrollbar { display: none; }
  .wizard-step { flex-shrink: 0; }
  .wizard-step-circle { width: 28px; height: 28px; font-size: .7rem; }
  .wizard-step-line { min-width: 12px; margin: 0 4px; }
  .wizard-step-label, .wizard-step-desc { display: none; }

  /* Output toolbar — icons only on tiny */
  .otb-btn span { display: none; }
  .otb-btn i { margin: 0; }
  .otb-btn { padding: 8px 12px; }
}

/* ── FADE DOWN ANIMATION FOR TOOLBAR ── */
@keyframes fadeDown {
