}
.sfp-left { display: flex; align-items: center; gap: 12px; flex: 1; min-width: 0; }
.sfp-right { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.sfp-label { font-size: .86rem; color: #d4af37; font-weight: 600; white-space: nowrap; }
