.sfp-tool-badge { display: flex; align-items: center; gap: 7px; padding: 5px 13px; background: rgba(0,212,255,.1); border-radius: 30px; font-size: .74rem; color: #00d4ff; white-space: nowrap; }
.sfp-stages-row { display: flex; gap: 6px; }
.sfp-stages-row .ssc-stage { font-size: .6rem; padding: 3px 9px; border-radius: 20px; background: rgba(255,255,255,.05); }
.sfp-stages-row .ssc-stage.active { background: rgba(0,212,255,.15); color: #00d4ff; }
.sfp-stages-row .ssc-stage.done  { background: rgba(0,255,136,.1);   color: #00ff88; }
.sfp-progress-track { height: 3px; background: rgba(255,255,255,.08); flex-shrink: 0; overflow: hidden; }
.sfp-progress-fill  { height: 100%; background: linear-gradient(90deg,#00d4ff,#d4af37); width: 4%; transition: width .4s ease; }
.sfp-scroll { flex: 1; overflow-y: auto; padding: 28px 40px; }

/* ── LIVE FORMATTED STREAM TEXT ───────────────────────────────────────────────── */
.sfp-text { font-family: 'Inter', sans-serif; font-size: .95rem; line-height: 1.8; color: #c8c8c8; word-wrap: break-word; }
.sfp-text.live-md { white-space: normal; }
.sfp-text.live-md h1 { font-size: 1.5rem; margin: 1em 0 .5em; background: linear-gradient(135deg,#fff,#d4af37); -webkit-background-clip: text; background-clip: text; color: transparent; }
.sfp-text.live-md h2 { font-size: 1.2rem; margin: .9em 0 .4em; background: linear-gradient(135deg,#00d4ff,#d4af37); -webkit-background-clip: text; background-clip: text; color: transparent; border-left: 3px solid #d4af37; padding-left: 12px; }
.sfp-text.live-md h3 { font-size: 1rem; color: #d4af37; margin: .8em 0 .3em; }
