.sfp-text.live-md code { background: rgba(0,0,0,.45); padding: 2px 8px; border-radius: 6px; font-family: var(--font-mono); font-size: .84em; color: #00d4ff; }
.sfp-text.live-md pre { background: rgba(0,0,0,.4); padding: 14px; border-radius: 10px; overflow-x: auto; margin: .8em 0; }
