/* ═══════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 42: DEMO SPOTLIGHT SYSTEM v2 — Canvas-based cutout tour
   ═══════════════════════════════════════════════════════════════════════════════════════════════════ */

/* Demo canvas overlay */
#demoCanvas {
  cursor: pointer;
}

/* Demo Tooltip Card */
#demoTooltip {
  font-family: var(--font-body);
  animation: demoSlideIn .28s cubic-bezier(.34,1.56,.64,1);
}

@keyframes demoSlideIn {
  from { opacity: 0; transform: translateY(12px) scale(.96); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Demo tooltip header */
.demo-tt-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.demo-tt-icon {
  width: 38px; height: 38px; flex-shrink: 0;
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
}

.demo-tt-title {
  flex: 1;
  font-size: .95rem;
  font-weight: 700;
  line-height: 1.3;
}

.demo-tt-close {
  background: transparent; border: none;
  color: rgba(255,255,255,.3); cursor: pointer;
  width: 28px; height: 28px; border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  transition: all .2s; font-size: .8rem;
}
.demo-tt-close:hover { color: #ff4444; background: rgba(255,68,68,.1); }

/* Step dots */
.demo-tt-dots {
  display: flex; gap: 5px; margin-bottom: 12px; flex-wrap: wrap;
}

.demo-dot {
  width: 26px; height: 26px; border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,.18);
  background: transparent;
  display: flex; align-items: center; justify-content: center;
  font-size: .65rem; font-weight: 700;
  color: rgba(255,255,255,.4);
  cursor: pointer; transition: all .2s;
}
.demo-dot:hover { border-color: #d4af37; color: #d4af37; }
.demo-dot.active {
  border-color: #00d4ff;
  background: rgba(0,212,255,.15);
  color: #00d4ff;
  animation: demoDotPulse 1.5s ease infinite;
}
.demo-dot.done {
  border-color: #00ff88;
  background: rgba(0,255,136,.12);
  color: #00ff88;
}
@keyframes demoDotPulse {
  0%,100% { box-shadow: 0 0 0 0 rgba(0,212,255,.4); }
  50%      { box-shadow: 0 0 0 5px rgba(0,212,255,0); }
}

/* Content */
.demo-tt-content {
  font-size: .84rem;
  line-height: 1.7;
  color: rgba(255,255,255,.8);
  margin-bottom: 12px;
}

/* Tips list */
.demo-tt-tips {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 16px;
  padding: 10px 12px;
  background: rgba(255,255,255,.04);
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,.07);
}

.demo-tip-row {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  font-size: .78rem;
  color: rgba(255,255,255,.72);
  line-height: 1.5;
}

.demo-tip-icon {
  color: #d4af37;
  font-size: .9rem;
  flex-shrink: 0;
  margin-top: 1px;
}

/* Footer buttons */
.demo-tt-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 14px;
  border-top: 1px solid rgba(255,255,255,.07);
}

.demo-tt-counter {
  flex: 1;
  text-align: center;
  font-size: .72rem;
  font-family: var(--font-mono);
  color: rgba(255,255,255,.4);
}

.demo-btn-prev, .demo-btn-next, .demo-btn-finish {
  width: 38px; height: 38px;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,.18);
  background: transparent;
  color: rgba(255,255,255,.7);
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  font-size: .9rem;
  transition: all .2s;
}
.demo-btn-prev:hover:not(:disabled), .demo-btn-next:hover {
  border-color: #d4af37;
  color: #d4af37;
  background: rgba(212,175,55,.1);
}
.demo-btn-prev:disabled { opacity: .3; cursor: not-allowed; }

.demo-btn-finish {
  width: auto; border-radius: 30px;
  padding: 0 16px;
  background: linear-gradient(135deg,#d4af37,#b8941f);
  border-color: transparent;
  color: #0a1128;
  font-size: .8rem;
  font-weight: 700;
  gap: 6px;
}
.demo-btn-finish:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(212,175,55,.4);
}

/* ── CLICK HINT at bottom ── */
.demo-canvas-hint {
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9998;
  font-size: .72rem;
  color: rgba(255,255,255,.5);
  background: rgba(0,0,0,.5);
  padding: 5px 14px;
  border-radius: 20px;
  pointer-events: none;
  font-family: var(--font-body);
  animation: demoPulseHint 2s ease infinite;
}
@keyframes demoPulseHint {
  0%,100% { opacity: .5; }
  50%      { opacity: 1; }
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 43: ENHANCED MOBILE GUI
   ═══════════════════════════════════════════════════════════════════════════════════════════════════ */

/* Better touch targets on mobile */
@media (max-width: 768px) {
  /* Larger nav items */
  .nav-item { padding: 12px 14px; }
  .nav-text  { font-size: .88rem; }

  /* Bigger buttons */
  .dh-btn { width: 38px; height: 38px; }

  /* Better scrolling */
  .out-area { -webkit-overflow-scrolling: touch; }

  /* Wizard: bigger tap targets */
  .wizard-tool-card { padding: 14px 12px; cursor: pointer; }
  .wizard-tool-card:active { transform: scale(.97); }

  /* Stats grid 4-col on most mobiles */
  .stats-grid-sidebar { grid-template-columns: repeat(4,1fr); }

  /* Output toolbar wraps nicely */
  .out-toolbar { padding: 8px 12px; gap: 5px; }
  .otb-btn { padding: 7px 10px; font-size: .72rem; }

  /* Larger flashcard */
  .fc-face { padding: 20px 16px; }
  .fc-wrap { max-width: 100%; }

  /* Quiz options full width */
  .quiz-opt-btn { padding: 12px 14px; }

  /* Demo tooltip full width on mobile */
  #demoTooltip { max-width: calc(100vw - 24px) !important; width: calc(100vw - 24px) !important; }
}

@media (max-width: 480px) {
  /* Compact header on tiny phones */
  .dh-logo .dh-text { display: none; }
  .dh-left { gap: 8px; }

  /* Stats 3-col on tiny screens */
  .stats-grid-sidebar { grid-template-columns: repeat(3,1fr); }

  /* Flashcard aspect ratio for small screens */
  .flashcard { aspect-ratio: 3/2; }

  /* Full-width mega generate button */
  .mega-generate-btn { font-size: .88rem; }

  /* Compact sidebar nav */
  .nav-item { padding: 10px 12px; }
  .nav-badge { font-size: .55rem; padding: 1px 6px; }
}

/* Touch feedback on interactive elements */
.nav-item:active, .wizard-tool-card:active, .fc-btn:active, .quiz-opt-btn:active {
  transform: scale(.97) !important;
}

/* Better mobile scrollbar */
@media (hover: none) {
  ::-webkit-scrollbar { width: 3px; }
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 44: SESSION INDICATOR IN SIDEBAR
   ═══════════════════════════════════════════════════════════════════════════════════════════════════ */

/* Sessions stat gets special highlight */
.stat-card-sidebar:nth-child(3) .stat-value-sidebar {
  background: linear-gradient(135deg,#00ff88,#00d4ff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 45: ENHANCED PDF BUTTON
   ═══════════════════════════════════════════════════════════════════════════════════════════════════ */

/* PDF button has two styles selectable */
#pdfBtn { position: relative; }
#pdfBtn::after {
  content: attr(data-theme);
  position: absolute;
  top: -6px; right: -6px;
  font-size: .5rem;
  padding: 2px 4px;
  background: rgba(212,175,55,.2);
  border-radius: 4px;
  color: #d4af37;
  pointer-events: none;
  white-space: nowrap;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 46: ENHANCED STREAM OVERLAY FOR ALL DEVICES
   ═══════════════════════════════════════════════════════════════════════════════════════════════════ */

/* Stream overlay takes full screen including behind sidebar on mobile */
@media (max-width: 1024px) {
  .stream-overlay {
    left: 0 !important;
    z-index: 600 !important;
  }
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 47: QUIZ DIFFICULTY BADGE SIZES
   ═══════════════════════════════════════════════════════════════════════════════════════════════════ */

.quiz-diff-badge {
  display: inline-block;
  font-size: .6rem;
  padding: 2px 8px;
  border-radius: 20px;
  font-weight: 600;
  text-transform: capitalize;
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════
   END SECTION 42-47
   ═══════════════════════════════════════════════════════════════════════════════════════════════════ */

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 48: LIVE CARD ANIMATION SYSTEM
   — Flashcards, Quiz, Mindmap appear one-by-one while streaming
   ═══════════════════════════════════════════════════════════════════════════════════════════════════ */

/* ── Common live stream wrapper ── */
.live-cards-wrapper,
.live-quiz-wrapper,
.live-mm-wrapper {
  padding: 0;
  animation: fadeIn .3s ease;
}

/* ── Header with progress bar ── */
.live-cards-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  flex-wrap: wrap;
  gap: 10px;
}

.live-cards-title {
  font-size: .88rem;
  font-weight: 700;
  color: #d4af37;
  display: flex;
  align-items: center;
  gap: 8px;
}

.live-cards-progress {
  display: flex;
  align-items: center;
  gap: 10px;
}

.live-cards-prog-bar {
  width: 120px;
  height: 4px;
  background: rgba(255,255,255,.08);
  border-radius: 4px;
  overflow: hidden;
}

.live-cards-prog-fill {
  height: 100%;
  background: linear-gradient(90deg,#bf00ff,#00d4ff);
  border-radius: 4px;
  transition: width .4s ease;
}

.live-cards-count {
  font-size: .7rem;
  color: rgba(255,255,255,.5);
  font-family: var(--font-mono);
  white-space: nowrap;
}

/* ── Flashcard grid ── */
.live-cards-grid {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: calc(100vh - 220px);
  overflow-y: auto;
  padding-right: 4px;
}

.live-card-item {
  background: rgba(191,0,255,.06);
  border: 1px solid rgba(191,0,255,.2);
  border-radius: 12px;
  padding: 12px 14px;
  animation: liveCardIn .4s cubic-bezier(.34,1.56,.64,1) both;
  transition: border-color .2s;
}

.live-card-item:hover {
  border-color: rgba(191,0,255,.4);
}

.live-card-new {
  border-color: rgba(191,0,255,.6) !important;
  box-shadow: 0 0 20px rgba(191,0,255,.2);
}

@keyframes liveCardIn {
  from { opacity:0; transform:translateX(-20px) scale(.96); }
  to   { opacity:1; transform:translateX(0)    scale(1); }
}

.live-card-num {
  font-size: .62rem;
  font-weight: 700;
  color: rgba(191,0,255,.7);
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: 5px;
}

.live-card-front {
  font-size: .86rem;
  font-weight: 600;
  color: #e0e0ff;
  margin-bottom: 6px;
  line-height: 1.5;
}

.live-card-back {
  font-size: .78rem;
  color: rgba(255,255,255,.55);
  line-height: 1.5;
  padding-left: 10px;
  border-left: 2px solid rgba(191,0,255,.3);
}

/* ── Quiz live list ── */
.live-quiz-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: calc(100vh - 220px);
  overflow-y: auto;
}

.live-quiz-item {
  background: rgba(0,255,136,.04);
  border: 1px solid rgba(0,255,136,.15);
  border-radius: 12px;
  padding: 12px 14px;
  animation: liveCardIn .4s cubic-bezier(.34,1.56,.64,1) both;
}

.live-quiz-item:hover { border-color: rgba(0,255,136,.3); }

.live-quiz-q-num {
  font-size: .7rem;
  font-weight: 700;
  color: rgba(0,255,136,.7);
  margin-bottom: 5px;
  display: flex;
  align-items: center;
  gap: 8px;
  text-transform: uppercase;
  letter-spacing: .05em;
}

.live-quiz-diff {
  font-size: .58rem;
  padding: 1px 7px;
  border-radius: 20px;
  font-weight: 600;
}
.live-diff-easy   { background: rgba(0,255,136,.15); color: #00ff88; }
.live-diff-medium { background: rgba(255,174,0,.15); color: #ffae00; }
.live-diff-hard   { background: rgba(255,68,68,.15); color: #ff6666; }

.live-quiz-q-text {
  font-size: .85rem;
  font-weight: 600;
  color: #e8e8ff;
  margin-bottom: 8px;
  line-height: 1.5;
}

.live-quiz-opts {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.live-quiz-opt {
  font-size: .75rem;
  color: rgba(255,255,255,.5);
  padding: 3px 8px;
  border-radius: 6px;
  transition: all .15s;
}

.live-quiz-correct {
  color: #00ff88 !important;
  background: rgba(0,255,136,.08);
  font-weight: 600;
}

/* ── Mind Map live ── */
.live-mm-central {
  text-align: center;
  padding: 12px 24px;
  background: linear-gradient(135deg,rgba(212,175,55,.12),rgba(0,212,255,.08));
  border: 1.5px solid rgba(212,175,55,.3);
  border-radius: 30px;
  font-size: .95rem;
  font-weight: 700;
  color: #d4af37;
  margin-bottom: 16px;
  animation: liveCardIn .5s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.live-mm-branches {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  max-height: calc(100vh - 250px);
  overflow-y: auto;
}

.live-mm-branch {
  flex: 1;
  min-width: 200px;
  background: rgba(255,255,255,.03);
  border-radius: 12px;
  padding: 12px;
  border-left: 3px solid #d4af37;
  animation: liveCardIn .5s cubic-bezier(.34,1.56,.64,1) both;
}

.live-mm-branch-name {
  font-size: .82rem;
  font-weight: 700;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 7px;
}

.live-mm-items {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.live-mm-item {
  font-size: .68rem;
  padding: 3px 9px;
  background: rgba(255,255,255,.05);
  border-radius: 20px;
  color: rgba(255,255,255,.65);
}

/* ── Loading & done indicators ── */
.live-cards-loading {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: .78rem;
  color: rgba(255,255,255,.4);
  padding: 12px 0 4px;
  font-style: italic;
}

.live-cards-done {
  font-size: .82rem;
  color: #00ff88;
  padding: 10px 0 4px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  animation: fadeIn .4s ease;
}

/* ── Animated dots ── */
.live-dots {
  display: flex;
  gap: 4px;
}
.live-dots span {
  width: 5px; height: 5px;
  background: #d4af37;
  border-radius: 50%;
  animation: liveDotPulse 1.2s ease infinite;
}
.live-dots span:nth-child(2) { animation-delay: .2s; }
.live-dots span:nth-child(3) { animation-delay: .4s; }
@keyframes liveDotPulse {
  0%,100% { opacity: .3; transform: scale(.8); }
  50%      { opacity: 1;  transform: scale(1.2); }
}

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════
   END SECTION 48
   ═══════════════════════════════════════════════════════════════════════════════════════════════════ */

/* ═══════════════════════════════════════════════════════════════════════════════════════════════════
   SECTION 49: WELCOME SCREEN — ACADEMIC STYLE + MANDATORY NAME + AVATAR
   ═══════════════════════════════════════════════════════════════════════════════════════════════════ */

/* ── Welcome modal body ── */
.welcome-modal-body {
  text-align: center;
  padding: 28px 32px 24px;
  max-height: 90vh;
  overflow-y: auto;
}

/* ── Graduation cap logo ── */
.welcome-cap-wrap {
  position: relative;
  display: inline-block;
  margin-bottom: 16px;
}

.welcome-cap {
  font-size: 3.8rem;
  line-height: 1;
  animation: welcomeCapBounce 1.5s ease infinite;
  display: block;
}

.welcome-sparkles {
  position: absolute;
  top: -6px; right: -10px;
  font-size: 1.2rem;
  animation: welcomeSparkle 2s ease infinite;
}

@keyframes welcomeCapBounce {
  0%,100% { transform: translateY(0) rotate(-3deg); }
  50%      { transform: translateY(-6px) rotate(3deg); }
}
@keyframes welcomeSparkle {
  0%,100% { opacity:1; transform:scale(1)rotate(0deg); }
  50%      { opacity:.6; transform:scale(1.3)rotate(20deg); }
}

/* ── Welcome brand name ── */
.welcome-brand {
  font-family: var(--font-brand);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #ffffff;
  font-weight: 800;
}

.welcome-brand-ai {
  color: #00d4ff;
}

.welcome-tagline {
  font-size: .88rem;
  font-style: italic;
  color: #d4af37;
  margin-bottom: 6px;
}

.welcome-subtitle {
  font-size: .78rem;
  color: rgba(255,255,255,.55);
  margin-bottom: 18px;
  line-height: 1.5;
}

/* ── Avatar selection ── */
.welcome-avatar-section {
  margin-bottom: 16px;
  text-align: left;
}

.welcome-avatar-label {
  font-size: .72rem;
  font-weight: 600;
  color: rgba(255,255,255,.5);
  text-transform: uppercase;
  letter-spacing: .07em;
  margin-bottom: 10px;
}

.welcome-avatar-grid {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
}

.wavatarBtn {
  width: 42px; height: 42px;
  border-radius: 50%;
  border: 2.5px solid transparent;
  cursor: pointer;
  font-size: .72rem;
  font-weight: 700;
  transition: all .25s;
  display: flex; align-items: center; justify-content: center;
  color: #fff;
}
.wavatarBtn:hover    { transform: scale(1.15); border-color: rgba(255,255,255,.5); }
.wavatarBtn.active   { border-color: #fff; transform: scale(1.1); box-shadow: 0 0 14px rgba(255,255,255,.4); }

/* ── Name input section ── */
.welcome-name-section {
  text-align: left;
  margin-bottom: 16px;
}

.welcome-name-label {
  display: block;
  font-size: .76rem;
  font-weight: 600;
  color: rgba(255,255,255,.6);
  margin-bottom: 8px;
}

.welcome-name-req {
  color: #ff6666;
  font-size: .8rem;
}

.welcome-input {
  width: 100%;
  padding: 13px 18px;
  background: rgba(255,255,255,.06);
  border: 1.5px solid rgba(255,255,255,.12);
  border-radius: 14px;
  font-size: .92rem;
  color: #ffffff;
  text-align: left;
  transition: all .25s;
  font-family: var(--font-body);
}
.welcome-input:focus {
  border-color: #00d4ff;
  background: rgba(0,212,255,.06);
  box-shadow: 0 0 0 3px rgba(0,212,255,.15);
  outline: none;
}
.welcome-input.name-ok  { border-color: #00ff88; }
.welcome-input.name-err { border-color: #ffae00; }

.welcome-name-hint {
  font-size: .72rem;
  margin-top: 6px;
  min-height: 16px;
  transition: all .25s;
  text-align: left;
}

/* ── Welcome CTA button ── */
.welcome-btn {
  width: 100%;
  padding: 14px;
  background: linear-gradient(135deg, #d4af37, #b8941f);
  border: none;
  border-radius: 14px;
  font-size: 1rem;
  font-weight: 800;
  color: #0a1128;
  cursor: pointer;
  transition: all .3s;
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  box-shadow: 0 4px 20px rgba(212,175,55,.35);
}
.welcome-btn:hover { transform: translateY(-2px); box-shadow: 0 8px 30px rgba(212,175,55,.5); }
.welcome-btn:active { transform: translateY(0); }

/* ── Feature chips ── */
.welcome-feature-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  justify-content: center;
  margin-bottom: 16px;
}

.wfeat {
  padding: 5px 13px;
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 30px;
  font-size: .72rem;
  color: rgba(255,255,255,.65);
  display: inline-flex;
  align-items: center;
