/* ═══════════════════════════════════════════════════════════════════════
   LIVE STREAM SCREEN — FINAL DESIGN (fixed: hidden by default)
   ═══════════════════════════════════════════════════════════════════════ */
.stream-overlay {
  position: fixed !important;
  inset: 0 !important;
  z-index: 9999 !important;
  display: none !important; /* hidden by default — JS toggles to flex */
  flex-direction: column !important;
  background:
    radial-gradient(1100px 620px at 15% -10%, rgba(0,212,255,.10), transparent 60%),
    radial-gradient(1000px 700px at 100% 110%, rgba(191,0,255,.09), transparent 55%),
    rgba(6,7,14,.97) !important;
  backdrop-filter: blur(22px) saturate(1.2) !important;
  -webkit-backdrop-filter: blur(22px) saturate(1.2) !important;
  animation: sfpFadeIn .35s cubic-bezier(.22,1,.36,1) !important;
  overflow: hidden !important;
}

/* When JS needs to show it, it will set display:flex via inline style */
.stream-overlay.active,
.stream-overlay[style*="display: flex"] {
  display: flex !important;
}

.stream-overlay.fading-out { 
  animation: sfpFadeOut .25s ease forwards !important; 
}
.stream-overlay.fading-out { animation: sfpFadeOut .25s ease forwards !important; }
@keyframes sfpFadeIn  { from { opacity: 0; } to { opacity: 1; } }
@keyframes sfpFadeOut { to { opacity: 0; } }

/* soft rotating aurora glow along the top edge */
.stream-overlay::before {
  content: '';
  position: absolute; top: -220px; left: 50%;
  width: 900px; height: 320px; transform: translateX(-50%);
  background: conic-gradient(from 0deg, #00d4ff, #bf00ff, #d4af37, #00ff88, #00d4ff);
  filter: blur(90px); opacity: .16;
  animation: sfpAurora 14s linear infinite;
  pointer-events: none; z-index: 0;
}
@keyframes sfpAurora { to { transform: translateX(-50%) rotate(360deg); } }

