.sfp-text.live-md code {
  background: rgba(0,0,0,.4) !important; padding: 2px 8px !important; border-radius: 6px !important;
  font-family: var(--font-mono) !important; font-size: .85em !important; color: #00d4ff !important;
}
.sfp-text.live-md pre { background: rgba(0,0,0,.4) !important; padding: 16px !important; border-radius: 12px !important; overflow-x: auto !important; margin: .9em 0 !important; }
.sfp-text.live-md hr { border: none !important; border-top: 1px solid rgba(255,255,255,.1) !important; margin: 1.6em 0 !important; }
.sfp-text.live-md strong { color: #ffffff !important; font-weight: 700 !important; }

.typing-cursor {
  display: inline-block !important; width: 9px !important; height: 1.05em !important;
  margin-left: 2px !important; vertical-align: text-bottom !important; border-radius: 2px !important;
  background: linear-gradient(180deg,#00d4ff,#bf00ff) !important;
  box-shadow: 0 0 10px rgba(0,212,255,.8) !important;
  animation: sfpCursorBlink .85s steps(1) infinite !important;
}
@keyframes sfpCursorBlink { 50% { opacity: 0; } }
.sfp-text.done .typing-cursor { display: none !important; }

/* ── live cards / quiz / mindmap generation panels ── */
.live-cards-wrapper, .live-quiz-wrapper, .live-mm-wrapper {
  max-width: 780px !important; margin: 0 auto !important;
  animation: sfpPanelIn .35s cubic-bezier(.22,1,.36,1) !important;
  background: rgba(255,255,255,.025) !important;
  border: 1px solid rgba(255,255,255,.07) !important;
  border-radius: 18px !important; padding: 20px 22px !important;
  backdrop-filter: blur(6px) !important;
}
@keyframes sfpPanelIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.live-cards-header { display: flex !important; align-items: center !important; justify-content: space-between !important; gap: 12px !important; flex-wrap: wrap !important; margin-bottom: 10px !important; }
.live-cards-title  { display: flex !important; align-items: center !important; gap: 8px !important; }
.live-cards-progress { display: flex !important; align-items: center !important; gap: 10px !important; flex: 1 !important; min-width: 160px !important; justify-content: flex-end !important; }
.live-cards-prog-bar { flex: 1 !important; max-width: 220px !important; overflow: hidden !important; background: rgba(255,255,255,.06) !important; }
.live-cards-count { font-size: .82rem !important; white-space: nowrap !important; }

.live-card-item, .live-quiz-item, .live-mm-branch {
  background: rgba(255,255,255,.035) !important;
  border-radius: 12px !important; padding: 12px 14px !important;
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease !important;
  animation: sfpTileIn .4s cubic-bezier(.34,1.56,.64,1) both !important;
}
.live-card-item:hover, .live-quiz-item:hover, .live-mm-branch:hover {
  transform: translateY(-2px) !important;
}
.live-card-new {
  box-shadow: 0 0 0 1px rgba(255,255,255,.08), 0 8px 24px rgba(0,0,0,.35) !important;
  animation: sfpTileIn .4s cubic-bezier(.34,1.56,.64,1) both, sfpNewGlow 1.4s ease-out !important;
}
@keyframes sfpTileIn { from { opacity: 0; transform: translateY(8px) scale(.97); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes sfpNewGlow { 0% { box-shadow: 0 0 0 2px rgba(0,212,255,.5), 0 0 28px rgba(0,212,255,.35); } 100% { box-shadow: 0 0 0 1px rgba(255,255,255,.08), 0 8px 24px rgba(0,0,0,.35); } }

.live-quiz-opt {
  background: rgba(255,255,255,.04) !important; border: 1px solid rgba(255,255,255,.08) !important;
  border-radius: 8px !important; color: rgba(255,255,255,.75) !important;
}
.live-quiz-correct {
  background: rgba(0,255,136,.1) !important; border-color: rgba(0,255,136,.4) !important; color: #00ff88 !important; font-weight: 700 !important;
}
.live-mm-item {
  background: rgba(255,255,255,.05) !important; border: 1px solid rgba(255,255,255,.08) !important;
  border-radius: 20px !important; color: rgba(255,255,255,.7) !important;
}

.live-cards-loading, .live-cards-done {
  display: flex !important; align-items: center !important; gap: 8px !important;
  padding: 10px 14px !important; border-radius: 10px !important; font-size: .82rem !important;
  background: rgba(255,255,255,.03) !important; border: 1px solid rgba(255,255,255,.06) !important;
}
.live-cards-done { background: rgba(0,255,136,.08) !important; border-color: rgba(0,255,136,.25) !important; color: #00ff88 !important; font-weight: 600 !important; }

.live-dots span {
  width: 6px !important; height: 6px !important; border-radius: 50% !important;
  animation: sfpDotBounce 1s ease-in-out infinite !important;
}
@keyframes sfpDotBounce { 0%,100%{ transform: translateY(0); opacity:.4; } 50%{ transform: translateY(-4px); opacity:1; } }

@media (max-width: 640px) {
  .sfp-header { padding: 14px 18px !important; }
  .sfp-fact   { margin: 0 18px 12px !important; }
  .sfp-stages-row { display: none !important; }
  .sfp-scroll { padding: 22px 16px 40px !important; }
  .stream-overlay::before { width: 500px; height: 200px; top: -140px; }
}
/* ────────────────────────────────────────────────────────────────────────
   LIGHT THEME CONTRAST SAFETY-NET
   Several older rules force white/near-white text colors that were written
   for the dark theme only and never got a light-theme override, causing
   invisible ("white on white") text in the output/content area. This block
   sits last in the cascade so it wins on equal specificity and restores
   readable contrast without touching the dark theme.
   ──────────────────────────────────────────────────────────────────────── */
[data-theme="light"] body,
[data-theme="light"] .app,
[data-theme="light"] .main-panel,
[data-theme="light"] .output-panel,
[data-theme="light"] .result-panel,
[data-theme="light"] .content-panel,
[data-theme="light"] .study-output,
[data-theme="light"] .out-panel {
  color: #1a1f3a;
}

[data-theme="light"] .md-content,
[data-theme="light"] .md-content *,
[data-theme="light"] .sfp-text,
[data-theme="light"] .sfp-text *,
[data-theme="light"] .study-sec,
[data-theme="light"] .study-sec *,
[data-theme="light"] .out-panel,
[data-theme="light"] .out-panel *,
[data-theme="light"] .result-panel,
[data-theme="light"] .result-panel *,
[data-theme="light"] .content-panel,
[data-theme="light"] .content-panel * {
  color: #1e2540;
}

/* Headings should stay dark and bold, not washed-out gray */
[data-theme="light"] .md-content h1,
[data-theme="light"] .md-content h2,
[data-theme="light"] .md-content h3,
[data-theme="light"] .md-content h4,
[data-theme="light"] .sfp-text h1,
[data-theme="light"] .sfp-text h2,
[data-theme="light"] .sfp-text h3,
[data-theme="light"] .sfp-text h4 {
  color: #0f1730;
}

/* Cards / chips / badges that use a translucent dark fill in dark mode need
   a light-mode fill so their text (often white) stays legible */
[data-theme="light"] .flashcard,
[data-theme="light"] .quiz-card,
[data-theme="light"] .mindmap-branch,
[data-theme="light"] .stat-card,
[data-theme="light"] .concept-card {
  background: rgba(255,255,255,.92);
  color: #1a1f3a;
  border-color: rgba(0,0,0,.1);
}
[data-theme="light"] .flashcard *,
[data-theme="light"] .quiz-card *,
[data-theme="light"] .mindmap-branch *,
[data-theme="light"] .stat-card *,
[data-theme="light"] .concept-card * {
  color: inherit;
}

/* Guard against any element accidentally left with a pure-white background
   AND default (often white) text — the classic invisible-text bug */
[data-theme="light"] [style*="background: #fff"],
[data-theme="light"] [style*="background:#fff"],
[data-theme="light"] [style*="background: white"] {
  color: #1a1f3a !important;
}
