  --aurora-cyan: #22d3ee;
  --aurora-violet: #a855f7;
  --aurora-pink: #ec4899;
  --aurora-teal: #14b8a6;
  --brass: #d4af37;
  --text-primary: #e5e7eb;
  --text-muted: rgba(255,255,255,.5);
  --border-glass: rgba(255,255,255,.08);
}

* { box-sizing: border-box; word-wrap: break-word; overflow-wrap: break-word; }
body { font-family: var(--font-display); }

/* Dashboard shell: sidebar in-flow on desktop, scroll ONLY on the far-right rail */
html, body {
  height: 100%;
  overflow: hidden;
}
.dash-body {
  height: 100%;
  overflow: hidden;
}
.sidebar, .left-panel, #leftPanel {
  position: relative;
  flex: none;
  width: 300px;
  max-width: 32vw;
  height: 100%;
  z-index: 100;
  background: var(--bg-surface);
  border-right: 1px solid var(--border-glass);
  overflow-y: auto;
}
.main-content, .right-panel, #rightPanel {
  margin-left: 0 !important;
  padding: 0 !important;
  min-height: 0 !important;
  flex: 1 1 auto;
  width: auto;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
#rightPanel .out-area,
.right-panel .out-area {
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  max-width: none !important;
  margin: 0 !important;
  padding: 20px 28px 28px !important;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-gutter: stable;
}

/* Mobile menu button */
.mobile-menu-btn {
  display: none;
  position: fixed;
  top: 16px; left: 16px;
  z-index: 200;
  background: var(--bg-surface);
  border: 1px solid var(--border-glass);
  color: var(--text-primary);
  width: 44px; height: 44px;
  border-radius: 12px;
  cursor: pointer;
  font-size: 1.2rem;
}

@media (max-width: 768px) {
  .mobile-menu-btn { display: flex; align-items: center; justify-content: center; }
  .sidebar, .left-panel, #leftPanel {
    position: fixed !important;
    left: 0; top: 0;
    width: 280px;
    max-width: 86vw;
    height: 100vh;
    transform: translateX(-100%);
    transition: transform 0.3s ease;
  }
  .sidebar.open, .left-panel.open, #leftPanel.mobile-open {
    transform: translateX(0);
  }
  .main-content, .right-panel, #rightPanel {
    margin-left: 0 !important;
    padding: 0 !important;
    width: 100%;
  }
  .hero h1 { font-size: 2rem !important; }
  .tier-grid { grid-template-columns: 1fr !important; }
}

/* Aurora buttons */
.btn-primary, .btn-buy, .buy-btn, .credit-btn-buy, .tier-buy-btn, .quick-buy-btn {
  background: linear-gradient(135deg, var(--aurora-cyan), #1970ff) !important;
  color: #fff !important;
  border: none !important;
  font-weight: 700;
  padding: 10px 20px;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: var(--font-display);
}

.btn-primary:hover, .btn-buy:hover, .buy-btn:hover, .credit-btn-buy:hover, .tier-buy-btn:hover, .quick-buy-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(34,211,238,.4);
}

/* 4-Tier Buy Modal Grid */
.tier-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  padding: 20px;
}

.tier-card {
  background: var(--bg-card);
  border: 1px solid var(--border-glass);
  border-radius: 16px;
  padding: 20px;
  text-align: center;
  transition: all 0.3s ease;
  position: relative;
  animation: fadeInUp 0.6s ease backwards;
  cursor: pointer;
}

.tier-card:nth-child(1) { animation-delay: .1s; }
.tier-card:nth-child(2) { animation-delay: .2s; }
.tier-card:nth-child(3) { animation-delay: .3s; }
.tier-card:nth-child(4) { animation-delay: .4s; }

.tier-card:hover {
  transform: translateY(-4px);
  border-color: var(--aurora-cyan);
  box-shadow: 0 12px 32px rgba(34,211,238,.2);
}

.tier-popular {
  background: linear-gradient(135deg, rgba(34,211,238,.1), rgba(25,112,255,.1));
  border: 2px solid var(--aurora-cyan);
}

.tier-badge {
  position: absolute;
  top: -10px; left: 50%;
  transform: translateX(-50%);
  background: linear-gradient(135deg, var(--brass), #b8941f);
  color: var(--bg-obsidian);
  padding: 4px 12px;
  border-radius: 12px;
  font-size: 0.7rem;
  font-weight: 800;
  white-space: nowrap;
}

.tier-icon { font-size: 2.5rem; margin-bottom: 8px; }
.tier-name { font-size: 1.2rem; font-weight: 800; color: #fff; margin-bottom: 4px; }
.tier-credits { font-size: 0.85rem; color: var(--text-muted); margin-bottom: 8px; }
.tier-price { font-size: 1.8rem; font-weight: 900; color: var(--aurora-cyan); margin-bottom: 4px; }
.tier-validity { font-size: 0.75rem; color: var(--text-muted); margin-bottom: 12px; }

/* WELCOME 10K Badge */
.welcome-badge, #creditPlanBadge {
  background: linear-gradient(135deg, rgba(34,211,238,.18), rgba(20,184,166,.1)) !important;
  border: 1px solid rgba(34,211,238,.3) !important;
  color: var(--aurora-cyan) !important;
  font-weight: 700 !important;
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 0.7rem;
  display: inline-block;
}

/* Animations */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

.animate-fadeInUp { animation: fadeInUp 0.6s ease; }
.animate-pulse { animation: pulse 2s ease infinite; }

/* Output typography */
.result-content, .md-content, .study-notes {
  font-family: var(--font-display);
  line-height: 1.7;
  color: var(--text-primary);
}

.result-content h1, .md-content h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.8rem;
  letter-spacing: -0.02em;
  margin: 1.5rem 0 1rem;
  color: #fff;
}

.result-content h2, .md-content h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.4rem;
  margin: 1.2rem 0 0.8rem;
  color: var(--aurora-cyan);
}

.result-content p, .md-content p {
  font-family: var(--font-display);
  line-height: 1.7;
  margin-bottom: 1rem;
}

.result-content code, .md-content code {
  font-family: var(--font-mono);
  background: rgba(34,211,238,.1);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.9em;
}

/* Credit History Modal */
.credit-history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background: var(--bg-card);
  border: 1px solid var(--border-glass);
  border-radius: 12px;
  margin-bottom: 8px;
  transition: all 0.2s ease;
}

.credit-history-item:hover {
  border-color: var(--aurora-cyan);
  transform: translateX(4px);
}

.credit-history-amount.positive { color: #10b981; font-weight: 700; }
.credit-history-amount.negative { color: #ef4444; font-weight: 700; }

/* Hero fix */
.hero-subtitle {
  font-family: var(--font-display);
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.6;
}

.hero-title {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 4rem;
  line-height: 1.1;
  letter-spacing: -0.03em;
  color: #fff;
  margin-bottom: 16px;
}

.hero-italic {
  font-family: var(--font-italic);
  font-style: italic;
  color: var(--brass);
}

@media (max-width: 768px) {
  .hero-title { font-size: 2.5rem; }
  .hero-subtitle { font-size: 0.95rem; padding: 0 16px; }
}

/* Remove Mesh API from dashboard footer */
.footer-mesh-api, .mesh-api-footer { display: none !important; }

/* ── Empty home canvas — fill the main pane, stay centered ── */
.empty-state {
  width: 100%;
  max-width: 820px;
  min-height: calc(100% - 24px);
  margin: 0 auto;
  padding: 6vh 16px 48px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.es-kicker {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: #22d3ee;
  margin-bottom: 18px;
}
.empty-state .es-title {
  font-family: Inter, -apple-system, sans-serif;
  font-weight: 800;
  font-size: clamp(2.2rem, 5vw, 3.6rem);
  letter-spacing: -0.035em;
  color: #fff;
  line-height: 1.05;
  margin-bottom: 16px;
}
.empty-state .es-title em {
  font-family: 'Instrument Serif', Georgia, serif;
  font-style: italic;
  font-weight: 400;
  color: #d4af37;
}
.empty-state .es-sub {
  color: rgba(255,255,255,.55);
  font-size: 1.02rem;
  line-height: 1.65;
  max-width: 540px;
  margin: 0 auto 28px;
}
.empty-wizard-btn, .empty-mega-btn, #emptyBuyBtn {
  min-height: 48px;
  border-radius: 14px !important;
}

/* ── Plan atelier modal ── */
#buyCreditsModal {
  align-items: center;
  justify-content: center;
  background: rgba(4,6,16,.78);
  backdrop-filter: blur(16px);
  z-index: 12000;
  padding: 20px;
}
.plan-atelier {
  position: relative;
  width: min(1080px, 100%);
  max-height: 92vh;
  overflow: auto;
  background: linear-gradient(180deg, #10162e 0%, #070c20 100%);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 28px;
  box-shadow: 0 40px 120px rgba(0,0,0,.55), 0 0 0 1px rgba(34,211,238,.08) inset;
}
.plan-atelier-glow {
  pointer-events: none;
  position: absolute; inset: 0;
  background:
    radial-gradient(60% 40% at 10% 0%, rgba(34,211,238,.14), transparent 55%),
    radial-gradient(50% 35% at 90% 10%, rgba(168,85,247,.12), transparent 55%);
}
.plan-atelier-hdr {
  position: relative;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 28px 28px 8px;
}
.plan-kicker {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: #22d3ee;
  margin-bottom: 8px;
}
.plan-atelier-hdr h3 {
  margin: 0 0 8px;
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -.03em;
  color: #fff;
}
.plan-atelier-hdr p {
  margin: 0;
  max-width: 560px;
  color: rgba(255,255,255,.52);
  line-height: 1.55;
  font-size: .92rem;
}
.plan-x {
  width: 40px; height: 40px; flex: none;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.12);
  background: rgba(255,255,255,.04);
  color: #fff;
  font-size: 1.4rem;
  cursor: pointer;
}
.plan-atelier-grid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  padding: 22px 24px 8px;
}
.plan-sheet {
  position: relative;
  background: rgba(255,255,255,.035);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 20px;
  padding: 22px 18px 18px;
  cursor: pointer;
  text-align: left;
  transition: transform .25s ease, border-color .25s ease, box-shadow .25s ease;
}
.plan-sheet:hover {
  transform: translateY(-6px);
  border-color: rgba(34,211,238,.45);
  box-shadow: 0 18px 40px rgba(34,211,238,.12);
}
.plan-sheet-star {
  background: linear-gradient(180deg, rgba(34,211,238,.12), rgba(25,112,255,.06));
  border: 2px solid #22d3ee;
}
.plan-sheet-top { display:flex; justify-content:space-between; align-items:center; margin-bottom: 8px; }
.plan-emoji { font-size: 1.6rem; }
.plan-role { font-size: .68rem; letter-spacing: .06em; text-transform: uppercase; color: rgba(255,255,255,.45); }
.plan-sheet h4 { margin: 0; font-size: 1.25rem; font-weight: 800; color: #fff; }
.plan-price { font-size: 2rem; font-weight: 900; color: #22d3ee; margin: 8px 0 2px; letter-spacing: -.03em; }
.plan-price small { font-size: .7rem; color: rgba(255,255,255,.45); font-weight: 600; }
.plan-credits { color: rgba(255,255,255,.62); font-size: .85rem; margin-bottom: 12px; }
.plan-facts { list-style: none; padding: 0; margin: 0 0 16px; display: grid; gap: 6px; }
.plan-facts li {
  font-size: .78rem;
  color: rgba(255,255,255,.7);
  padding-left: 14px;
  position: relative;
}
.plan-facts li::before {
  content: '';
  position: absolute; left: 0; top: 7px;
  width: 6px; height: 6px; border-radius: 50%;
  background: #22d3ee;
}
.plan-atelier-foot {
  position: relative;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 28px 24px;
  color: rgba(255,255,255,.45);
  font-size: .78rem;
}
@media (max-width: 980px) {
  .plan-atelier-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 640px) {
  .plan-atelier-grid { grid-template-columns: 1fr; }
  .plan-atelier-hdr { padding: 20px 16px 4px; }
  .plan-atelier-grid { padding: 16px; }
}

/* ══════════════════════════════════════════════════════════════════════════════
   SAVOIRÉ — SINGLE FILE LOCK (style.css only)
   Phone + PC · dark / light / golden · colored stats · liquid dock
   ══════════════════════════════════════════════════════════════════════════════ */

:root{
  --sv-cyan:#22d3ee; --sv-blue:#1970ff; --sv-gold:#d4af37; --sv-gold2:#f0d27a;
  --sv-violet:#8b5cf6; --sv-green:#34d399; --sv-pink:#f472b6; --sv-orange:#fb923c;
  --sv-red:#f87171; --sv-text:#e8eef8; --sv-muted:rgba(232,238,248,.58);
  --sv-line:rgba(255,255,255,.10); --sv-obsidian:#060a18;
  --sv-aurora:linear-gradient(135deg,#22d3ee,#1970ff);
  --sv-goldg:linear-gradient(135deg,#f0d27a,#d4af37);
  --sv-safe-b:env(safe-area-inset-bottom,0px);
  --sv-safe-t:env(safe-area-inset-top,0px);
  --sv-ease:cubic-bezier(.22,1,.36,1);
}

html[data-theme="light"]{
  --sv-obsidian:#f3f6fb; --sv-text:#152033; --sv-muted:rgba(21,32,51,.55);
  --sv-line:rgba(15,23,42,.10);
}
html[data-theme="golden"]{ --sv-cyan:#f0d27a; }

/* Colored stats — screenshot grid */
.stats-grid-sidebar{
  display:grid !important;
  grid-template-columns:repeat(4,minmax(0,1fr)) !important;
  gap:10px !important;
  padding:8px 14px 16px !important;
}
.stat-card-sidebar{
  border-radius:16px !important;
  padding:14px 8px 12px !important;
  text-align:center !important;
  background:rgba(255,255,255,.04) !important;
  border:1px solid rgba(255,255,255,.08) !important;
  min-height:76px;
  transition:transform .22s var(--sv-ease), border-color .22s, box-shadow .22s;
}
.stat-card-sidebar:hover{ transform:translateY(-3px); }
.stat-value-sidebar{
  font-size:1.15rem !important;
  font-weight:800 !important;
  line-height:1.1;
  background:none !important;
  -webkit-text-fill-color:unset !important;
  color:#fff !important;
}
.stat-label-sidebar{
  margin-top:6px !important;
  font-size:.58rem !important;
  letter-spacing:.08em;
  text-transform:uppercase;
  color:rgba(255,255,255,.42) !important;
}
.stat-label-sidebar i{ margin-right:3px; }

.stats-grid-sidebar .stat-card-sidebar:nth-child(1){
  border-color:rgba(251,146,60,.28) !important;
  background:radial-gradient(120% 80% at 50% 0%,rgba(251,146,60,.16),rgba(255,255,255,.03)) !important;
}
.stats-grid-sidebar .stat-card-sidebar:nth-child(1) .stat-value-sidebar{ color:#fb923c !important; }
.stats-grid-sidebar .stat-card-sidebar:nth-child(1) .stat-label-sidebar,
.stats-grid-sidebar .stat-card-sidebar:nth-child(1) .stat-label-sidebar i{ color:#fb923c !important; }

.stats-grid-sidebar .stat-card-sidebar:nth-child(2){
  border-color:rgba(240,210,122,.3) !important;
  background:radial-gradient(120% 80% at 50% 0%,rgba(212,175,55,.16),rgba(255,255,255,.03)) !important;
}
.stats-grid-sidebar .stat-card-sidebar:nth-child(2) .stat-value-sidebar{ color:#f0d27a !important; }
.stats-grid-sidebar .stat-card-sidebar:nth-child(2) .stat-label-sidebar,
.stats-grid-sidebar .stat-card-sidebar:nth-child(2) .stat-label-sidebar i{ color:#f0d27a !important; }

.stats-grid-sidebar .stat-card-sidebar:nth-child(3){
  border-color:rgba(34,211,238,.32) !important;
  background:radial-gradient(120% 80% at 50% 0%,rgba(34,211,238,.16),rgba(255,255,255,.03)) !important;
}
.stats-grid-sidebar .stat-card-sidebar:nth-child(3) .stat-value-sidebar{ color:#22d3ee !important; }
.stats-grid-sidebar .stat-card-sidebar:nth-child(3) .stat-label-sidebar,
.stats-grid-sidebar .stat-card-sidebar:nth-child(3) .stat-label-sidebar i{ color:#22d3ee !important; }

.stats-grid-sidebar .stat-card-sidebar:nth-child(4){
  border-color:rgba(139,92,246,.3) !important;
  background:radial-gradient(120% 80% at 50% 0%,rgba(139,92,246,.16),rgba(255,255,255,.03)) !important;
}
.stats-grid-sidebar .stat-card-sidebar:nth-child(4) .stat-value-sidebar{ color:#c4b5fd !important; }
.stats-grid-sidebar .stat-card-sidebar:nth-child(4) .stat-label-sidebar,
.stats-grid-sidebar .stat-card-sidebar:nth-child(4) .stat-label-sidebar i{ color:#c4b5fd !important; }

.stats-grid-sidebar .stat-card-sidebar:nth-child(5){
  border-color:rgba(244,114,182,.28) !important;
  background:radial-gradient(120% 80% at 50% 0%,rgba(244,114,182,.14),rgba(255,255,255,.03)) !important;
}
.stats-grid-sidebar .stat-card-sidebar:nth-child(5) .stat-value-sidebar{ color:#f9a8d4 !important; }
.stats-grid-sidebar .stat-card-sidebar:nth-child(5) .stat-label-sidebar,
.stats-grid-sidebar .stat-card-sidebar:nth-child(5) .stat-label-sidebar i{ color:#f9a8d4 !important; }

.stats-grid-sidebar .stat-card-sidebar:nth-child(6){
  border-color:rgba(52,211,153,.3) !important;
  background:radial-gradient(120% 80% at 50% 0%,rgba(52,211,153,.14),rgba(255,255,255,.03)) !important;
}
.stats-grid-sidebar .stat-card-sidebar:nth-child(6) .stat-value-sidebar{ color:#6ee7b7 !important; }
.stats-grid-sidebar .stat-card-sidebar:nth-child(6) .stat-label-sidebar,
.stats-grid-sidebar .stat-card-sidebar:nth-child(6) .stat-label-sidebar i{ color:#6ee7b7 !important; }

.stats-grid-sidebar .stat-card-sidebar:nth-child(7){
  grid-column:span 2;
  border-color:rgba(96,165,250,.3) !important;
  background:radial-gradient(120% 80% at 50% 0%,rgba(59,130,246,.16),rgba(255,255,255,.03)) !important;
}
.stats-grid-sidebar .stat-card-sidebar:nth-child(7) .stat-value-sidebar{ color:#93c5fd !important; font-size:1.05rem !important; }
.stats-grid-sidebar .stat-card-sidebar:nth-child(7) .stat-label-sidebar,
.stats-grid-sidebar .stat-card-sidebar:nth-child(7) .stat-label-sidebar i{ color:#93c5fd !important; }

html[data-theme="light"] .stat-card-sidebar{
  background:#fff !important;
  border-color:rgba(15,23,42,.08) !important;
}
html[data-theme="light"] .stat-value-sidebar{ filter:saturate(1.1); }

/* Buttons / commerce always clickable */
.credit-btn,.credit-btn-buy,.credit-btn-history,.quick-buy-btn,.tier-buy-btn,
.plan-sheet,.plan-x,#svDock button,.empty-wizard-btn,.empty-mega-btn,#emptyBuyBtn,
.nav-item,.wizard-btn,.mega-generate-btn{
  pointer-events:auto !important; cursor:pointer !important; position:relative; z-index:2;
}
.credit-btn-buy,.quick-buy-btn,.tier-buy-btn,.empty-wizard-btn,.wizard-btn-primary,.mega-generate-btn,.welcome-btn,.wb-btn,.confirm-btn.ok{
  background:var(--sv-aurora) !important; color:#fff !important; border:0 !important;
  min-height:44px; border-radius:14px; font-weight:700;
}
.empty-mega-btn{ background:var(--sv-goldg) !important; color:#140f00 !important; }
.credit-btn-buy::after,.btn::before,a::after{ pointer-events:none !important; }

/* Output never strips */
#resultArea,.result-wrap,.study-sec,.ss-body,.md-content,#liveNotesContent{
  display:block !important; width:100% !important; max-width:100% !important;
  height:auto !important; white-space:normal !important;
}
.md-content h1,.md-content h2,.md-content h3,.rh-topic,.es-title,.modal-title,.wizard-step-heading{
  background:none !important; -webkit-text-fill-color:unset !important;
}
.md-content h1{ color:#f0d27a !important; }
.md-content h2{ color:#7dd3fc !important; }
.md-content p,.md-content li,.li-text{ color:#e6ebf7 !important; white-space:normal !important; line-height:1.8 !important; }
html[data-theme="light"] .md-content p,html[data-theme="light"] .li-text{ color:#1e293b !important; }

.es-title em,.welcome-tagline em,.user-tagline-sidebar em{
  font-family:'Instrument Serif',Georgia,serif !important;
  font-style:italic !important; color:#d4af37 !important; font-weight:400 !important;
}

#buyCreditsOverlay,.gold-rail,.side-gold{ display:none !important; }
